mapper.select:
select c.id, c.organization_id, c.doc_id, c.seq, c.content, c.vector, c.create_time, c.update_time, c.create_user, c.update_user from ai_knowledge_chunk c join ai_knowledge_doc d on c.doc_id = d.id where c.organization_id = #{orgId} and d.revoked = 0 and (d.effective_date is null or d.effective_date <= curdate())
and (
c.content like concat('%', #{kw}, '%')
)
order by c.create_time desc limit #{limit}

mapper.delete:
delete from ai_knowledge_chunk
where organization_id = #{orgId}
  and doc_id = #{docId}

mapper.update:
update ai_knowledge_chunk
set vector = #{vector}
where id = #{id}
